const BarcodeScannerComponent = ({ 
  onResult, 
  onClose,
  facingMode = "environment"
}: { 
  onResult: (text: string) => void; 
  onClose?: () => void;
  facingMode?: "environment" | "user";
}) => {
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;
    setError(null);
    const html5QrCode = new Html5Qrcode("reader");
    
    const config = { 
      fps: 25, 
      qrbox: { width: 70, height: 70 },
      aspectRatio: 1.2
    };

    const startScanner = async () => {
      try {
        await html5QrCode.start(
          { facingMode: facingMode }, 
          config, 
          (decodedText) => {
            if (!isMounted) return;
            onResult(decodedText);
            if (html5QrCode.isScanning) {
              html5QrCode.stop().catch(err => console.error("Error stopping scanner after scan", err));
            }
          },
          undefined
        );
      } catch (err: any) {
        if (!isMounted) return;
        const errStr = err.toString();
        console.warn("Camera access failed:", errStr);
        if (errStr.includes("NotAllowedError") || errStr.includes("Permission denied")) {
          setError("Izin Kamera Ditolak");
        } else {
          setError("Gagal Kamera");
        }
      }
    };

    startScanner();

    return () => {
      isMounted = false;
      if (html5QrCode.isScanning) {
        html5QrCode.stop().catch(err => console.log("Scanner cleaned up"));
      }
    };
  }, [onResult, facingMode]);

  return (
    <div className="relative w-16 h-10 bg-black rounded-lg overflow-hidden border-2 border-[#F15A24] shrink-0 flex items-center justify-center shadow-sm">
      <div id="reader" className="w-full h-full object-cover" />
      {error && (
        <div className="absolute inset-0 bg-rose-600/90 text-white text-[7px] font-black p-0.5 text-center flex items-center justify-center leading-tight">
          {error}
        </div>
      )}
    </div>
  );
};;

const getCategoryIcon = (category: string) => {
  const cat = category.toLowerCase();
  if (cat === "semua") return <Grid className="w-3.5 h-3.5" />;
  if (
    cat.includes("makan") || 
    cat.includes("cemilan") || 
    cat.includes("snack") || 
    cat.includes("roti") || 
    cat.includes("biskuit") || 
    cat.includes("biscuit") || 
    cat.includes("kuliner")
  ) {
    return <Cookie className="w-3.5 h-3.5" />;
  }
  if (
    cat.includes("minum") || 
    cat.includes("soda") || 
    cat.includes("kopi") || 
    cat.includes("teh") || 
    cat.includes("susu") || 
    cat.includes("jus") || 
    cat.includes("beverage")
  ) {
    return <CupSoda className="w-3.5 h-3.5" />;
  }
  if (
    cat.includes("sembako") || 
    cat.includes("beras") || 
    cat.includes("minyak") || 
    cat.includes("bumbu") || 
    cat.includes("gula") || 
    cat.includes("mie") || 
    cat.includes("telur") || 
    cat.includes("dapur")
  ) {
    return <ShoppingBag className="w-3.5 h-3.5" />;
  }
  if (
    cat.includes("rokok") || 
    cat.includes("korek") || 
    cat.includes("tembakau") || 
    cat.includes("api")
  ) {
    return <Flame className="w-3.5 h-3.5" />;
  }
  if (
    cat.includes("sabun") || 
    cat.includes("shampoo") || 
    cat.includes("mandi") || 
    cat.includes("cuci") || 
    cat.includes("odol") || 
    cat.includes("shampo") || 
    cat.includes("pembersih") || 
    cat.includes("beauty") || 
    cat.includes("kecantikan") || 
    cat.includes("detergen")
  ) {
    return <Sparkles className="w-3.5 h-3.5" />;
  }
  if (
    cat.includes("obat") || 
    cat.includes("sakit") || 
    cat.includes("vitamin") || 
    cat.includes("medis") || 
    cat.includes("kesehatan") || 
    cat.includes("p3k")
  ) {
    return <Pill className="w-3.5 h-3.5" />;
  }
  if (
    cat.includes("atk") || 
    cat.includes("tulis") || 
    cat.includes("buku") || 
    cat.includes("pensil") || 
    cat.includes("pulpen") || 
    cat.includes("kertas") || 
    cat.includes("kantor")
  ) {
    return <Pencil className="w-3.5 h-3.5" />;
  }
  return <Package className="w-3.5 h-3.5" />;
};

export const ProductImage: React.FC<{ 
  src?: string | null; 
  alt?: string; 
  className?: string; 
  iconClassName?: string;
}> = ({ 
  src, 
  alt = "Produk", 
  className = "w-full h-full object-cover", 
  iconClassName = "w-10 h-10 text-slate-300 dark:text-slate-600" 
}) => {
  const [hasError, setHasError] = useState(false);
  const formattedUrl = useMemo(() => formatImageUrl(src), [src]);

  if (!formattedUrl || hasError) {
    return (
      <div className="w-full h-full flex items-center justify-center bg-slate-50 dark:bg-slate-800/80">
        <Package className={iconClassName} />
      </div>
    );
  }

  return (
    <img
      src={formattedUrl}
      alt={alt}
      className={className}
      loading="lazy"
      decoding="async"
      referrerPolicy="no-referrer"
      onError={() => setHasError(true)}
    />
  );
};

