const detectProvider = (number: string): ProviderInfo | null => {
  const clean = number.replace(/\D/g, '');
  if (clean.length < 4) return null;
  const prefix4 = clean.slice(0, 4);
  return PROVIDERS.find(p => p.prefixes.includes(prefix4)) || null;
};

